void
j2x_interrupts_array_deinit(
    int unit)
{
    soc_interrupt_db_t *j2x_interrupts;
    soc_interrupt_tree_t *j2x_interrupt_tree;
    int inter = 0;
    SHR_FUNC_INIT_VARS(unit);

    if (NULL == SOC_CONTROL(unit)->interrupts_info)
    {
        SHR_EXIT();
    }

    j2x_interrupts = SOC_CONTROL(unit)->interrupts_info->interrupt_db_info;
    j2x_interrupt_tree = SOC_CONTROL(unit)->interrupts_info->interrupt_tree_info;

    for (inter = 0; inter < J2X_INT_LAST; inter++)
    {
        if (j2x_interrupts[inter].statistics_count != NULL)
        {
            sal_free(j2x_interrupts[inter].statistics_count);
            j2x_interrupts[inter].statistics_count = NULL;
        }
        if (j2x_interrupts[inter].storm_nominal_count != NULL)
        {
            sal_free(j2x_interrupts[inter].storm_nominal_count);
            j2x_interrupts[inter].storm_nominal_count = NULL;
        }
        if (j2x_interrupts[inter].storm_detection_occurrences != NULL)
        {
            sal_free(j2x_interrupts[inter].storm_detection_occurrences);
            j2x_interrupts[inter].storm_detection_occurrences = NULL;
        }
        if (j2x_interrupts[inter].storm_detection_start_time != NULL)
        {
            sal_free(j2x_interrupts[inter].storm_detection_start_time);
            j2x_interrupts[inter].storm_detection_start_time = NULL;
        }
    }

    if (j2x_interrupts != NULL)
    {
        sal_free(j2x_interrupts);
        SOC_CONTROL(unit)->interrupts_info->interrupt_db_info = NULL;
    }

    if (j2x_interrupt_tree != NULL)
    {
        sal_free(j2x_interrupt_tree);
        SOC_CONTROL(unit)->interrupts_info->interrupt_tree_info = NULL;
    }

    if (SOC_CONTROL(unit)->interrupts_info != NULL)
    {
        sal_free(SOC_CONTROL(unit)->interrupts_info);
        SOC_CONTROL(unit)->interrupts_info = NULL;
    }

exit:
    SHR_VOID_FUNC_EXIT;
}

